const requeuePackageArtifactAfterFailure = `-- name: RequeuePackageArtifactAfterFailure :one
UPDATE package_artifacts
SET status = CASE
        WHEN attempts < ?1 THEN 'pending'
        ELSE 'failed'
    END,
    progress_bytes = 0,
    error = CASE
        WHEN attempts < ?1 THEN NULL
        ELSE ?2
    END,
    updated_at = CURRENT_TIMESTAMP
WHERE id = ?3 AND status = 'building'
RETURNING id, package_id, kind, filename, size, source_size, position, status, progress_bytes, access_count, attempts, object_key, error, created_at, updated_at
`

type RequeuePackageArtifactAfterFailureParams struct {
	MaxAttempts int64
	Error       sql.NullString
	ID          string
}

// Keep retryable failures out of the externally visible failed state. This is
// one transition so even another worker can never mistake a retry window for a
// terminal package failure.
func (q *Queries) RequeuePackageArtifactAfterFailure(ctx context.Context, arg RequeuePackageArtifactAfterFailureParams) (PackageArtifact, error) {
	row := q.db.QueryRowContext(ctx, requeuePackageArtifactAfterFailure, arg.MaxAttempts, arg.Error, arg.ID)
	var i PackageArtifact
	err := row.Scan(
		&i.ID,
		&i.PackageID,
		&i.Kind,
		&i.Filename,
		&i.Size,
		&i.SourceSize,
		&i.Position,
		&i.Status,
		&i.ProgressBytes,
		&i.AccessCount,
		&i.Attempts,
		&i.ObjectKey,
		&i.Error,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

